    invoiceNumber: '',
    requisitionNumber: '',
    odometer: 0,
    dailyKm: 0
  });

  // External Equipment State
  const [isExternal, setIsExternal] = useState(false);
  const [externalData, setExternalData] = useState({
    identifier: '', // Placa ou Nome (Barco, Balsa)
