                <span className="uppercase font-bold text-slate-600">Tempo Operação:</span>
                <span>{summary.formattedTime}</span>
            </div>
            <div className="flex items-center gap-1">
                <span className="uppercase font-bold text-slate-600">KM Total:</span>
                <span>{summary.totalKm} km</span>
            </div>
            <div className="flex items-center gap-1">
                <span className="uppercase font-bold text-slate-600">Sem Sinal:</span>
                <span>{summary.daysNoSignal} dias</span>
            </div>
            <div className="flex items-center gap-1">
                <span className="uppercase font-bold text-slate-600">Parado:</span>
                <span>{summary.daysStopped} dias</span>
            </div>
        </div>

