Para corrigir o erro crítico de "Timeout" e "Falha ao buscar perfil", que impede o login e o uso do sistema, vou realizar duas intervenções fundamentais:

1.  **Correção no `index.html`**: O arquivo atual contém um bloco `importmap` que força o uso do React 19 via CDN, o que entra em conflito com o React 18 instalado no projeto (Vite). Isso causa instabilidade e erros de carregamento silenciosos. Vou remover esse bloco.
2.  **Robustez no `AuthContext.tsx`**:
    *   Aumentarei o tempo limite (Timeout) para 20 segundos (o banco de dados pode demorar a "acordar").
    *   Adicionarei uma lógica de **Auto-Reparo**: Se o sistema não encontrar o perfil do usuário (`PGRST116`), ele tentará criar o perfil automaticamente (como 'OPERADOR') e buscará novamente. Isso resolve casos onde o cadastro inicial falhou ou o gatilho de banco de dados não disparou.

Aqui estão os arquivos corrigidos:

# Updated files:

## index.html

Remoção do `importmap` conflitante para garantir a estabilidade do React e evitar erros de script.

## contexts/AuthContext.tsx

Implementação de timeout estendido (20s) e lógica de "Auto-Reparo" para criar o perfil do usuário caso ele não exista, prevenindo o erro crítico de login.

```tsx
import React, { createContext, useContext, useEffect, useState, useRef } from 'react';
import { supabase } from '../services/supabaseClient';
import { UserProfile, UserRole } from '../types';
import { Session } from '@supabase/supabase-js';

interface AuthContextType {
  session: Session | null;
  user: UserProfile | null;
  loading: boolean;
  signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [session, setSession] = useState<Session | null>(null);
  const [user, setUser] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);

  const loadedUserId = useRef<string | null>(null);

  const parseRole = (roleRaw: string): UserRole => {
    if (!roleRaw) return UserRole.OPERADOR;
    const normalized = roleRaw.toUpperCase().trim();
    if (Object.values(UserRole).includes(normalized as UserRole)) {
      return normalized as UserRole;
    }
    return UserRole.OPERADOR;
  };

  const fetchUserProfile = async (userId: string, email: string) => {
    let attempts = 0;
    let success = false;
    const maxRetries = 3;

    while (attempts < maxRetries && !success) {
      attempts++;
      try {
        // Timeout aumentado para 20s para lidar com cold starts do DB
        const timeoutPromise = new Promise((_, reject) => 
          setTimeout(() => reject(new Error('Timeout')), 20000)
        );

        const fetchPromise = supabase
          .from('user_roles')
          .select('*')
          .eq('id', userId)
          .single();

        const response: any = await Promise.race([fetchPromise, timeoutPromise]);

        if (response.error) {
          // Se o perfil não for encontrado (PGRST116), tentamos criar um fallback
          if (response.error.code === 'PGRST116') {
             console.warn(`Perfil não encontrado na tentativa ${attempts}. Tentando auto-reparo...`);

             // Tenta criar o perfil manualmente se o trigger falhou
             const { error: insertError } = await supabase
                .from('user_roles')
                .insert([{ id: userId, email: email, role: 'OPERADOR' }]);

             if (!insertError) {
                 console.log("Perfil criado com sucesso via auto-reparo.");
                 // Lança erro genérico para forçar o loop a tentar o fetch novamente na próxima iteração
                 throw new Error("Profile created, retrying fetch");
             } else {
                 console.error("Falha no auto-reparo:", insertError);
             }
          }
          throw response.error;
        } 

        if (response.data) {
          const safeRole = parseRole(response.data.role);
          setUser({ id: userId, email, role: safeRole, name: response.data.name });
          loadedUserId.current = userId;
          success = true;
        }
      } catch (e) {
        console.warn(`Erro na tentativa ${attempts} de ${maxRetries} ao buscar perfil:`, e);

        if (attempts < maxRetries) {
          // Backoff exponencial: 1s, 2s...
          await new Promise(resolve => setTimeout(resolve, attempts * 1000));
        }
      }
    }

    if (!success) {
      console.error('Falha crítica: Não foi possível carregar o perfil após múltiplas tentativas.');
      setUser(null);
      loadedUserId.current = null;
    }

    setLoading(false);
  };

  useEffect(() => {
    let mounted = true;

    const initializeAuth = async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();

        if (mounted) {
          setSession(session);
          if (session?.user) {
             await fetchUserProfile(session.user.id, session.user.email!);
          } else {
             setLoading(false);
          }
        }
      } catch (error) {
        console.error("Auth init error:", error);
        if (mounted) setLoading(false);
      }
    };

    initializeAuth();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (_event, session) => {
      if (!mounted) return;

      setSession(session);

      if (session?.user) {
        if (loadedUserId.current === session.user.id) {
            setLoading(false);
            return;
        }
        await fetchUserProfile(session.user.id, session.user.email!);
      } else {
        setUser(null);
        loadedUserId.current = null;
        setLoading(false);
      }
    });

    return () => {
      mounted = false;
      subscription.unsubscribe();
    };
  }, []);

  const signOut = async () => {
    setLoading(true);
    try {
      await supabase.auth.signOut();
    } catch (error) {
      console.error("Error signing out:", error);
    } finally {
      setSession(null);
      setUser(null);
      loadedUserId.current = null;
      setLoading(false);
    }
  };

  return (
    <AuthContext.Provider value={{ session, user, loading, signOut }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
