                                                    <div className="flex items-center gap-1">
                                                        <span className="font-bold text-slate-800">{item.plateSnapshot}</span>
                                                        {isExt && <AlertCircle size={12} className="text-orange-500" title="Externo / Não Cadastrado" />}
